const W=eval(load("wttjHelpers"));
async function search(name,title="Software Engineer"){
await W.nav("tab_j","https://www.welcometothejungle.com/fr/jobs-matches");
await W.ev("tab_j","(()=>{const b=[...document.querySelectorAll('button')].find(x=>x.innerText==='Rôle');const i=document.querySelector('input[placeholder*=Product]');if(!i.getBoundingClientRect().height)b.click();Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(i,"+JSON.stringify(title)+");i.dispatchEvent(new Event('input',{bubbles:true}));return true})()");
await W.ev("tab_j","(()=>{const x=document.querySelector('input[name=locations]');if(!x?.getBoundingClientRect().height)document.querySelector('[data-testid=filter-accordion-location]').click();return true})()");
for(let i=0;i<5;i++){const has=await W.ev("tab_j","!!document.querySelector('[data-testid=location-tag-0] button')");if(!has)break;await W.ev("tab_j","document.querySelector('[data-testid=location-tag-0] button').click();true");await W.delay(150);}
await W.ev("tab_j","(()=>{const x=document.querySelector('input[name=locations]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(x,"+JSON.stringify(name)+");x.dispatchEvent(new Event('input',{bubbles:true}));return true})()");
await W.delay(1500);const opts=await W.ev("tab_j","[...document.querySelectorAll('[role=option]')].map(x=>x.innerText)");text(opts.slice(0,2));if(!opts.length)throw Error("No location option");await W.ev("tab_j","document.querySelector('[role=option]').click();true");await W.delay(500);await W.ev("tab_j","document.querySelector('[data-testid=filters-save-button]').click();true");await W.delay(1300);store("wttjSearchLocation",name==="États-Unis"?"US":name);text(await W.ev("tab_j","document.body.innerText.slice(0,900)"));return eval(load("roundHelpers")).round();
}
({search,W})
